#!/usr/bin/env bash
# Builds the deployable pages from their body-fragment sources in src/ (the same fragments are used for the hosted previews).
# Host-only preview tags (<meta name="claude:...">) are stripped so the built pages carry no tool marks.
#   src/immersive.html  -> ./immersive.html   (First Light, the scroll-driven version)
#   src/advantage.html  -> ./advantage.html   (CNESS Advantage subpage; generated by tools/build-advantage.py)
#   src/certification.html -> ./certification.html (Certification section, three routed pages; generated by tools/build-certification.py)
#   src/analyze.html    -> ./analyze.html     (Analyze: Organization and Product self-assessment; generated by tools/build-analyze.py)
#   src/directory.html  -> ./directory.html   (Global Directory: search, filters and listings over a snapshot; generated by tools/build-directory.py)
#   src/global.html     -> ./global.html      (Global landing page: the site header, with global-template.html, the /global Site Template, in a frame)
set -euo pipefail
cd "$(dirname "$0")"
for name in immersive advantage certification analyze directory global; do
  src="src/$name.html"
  [ -f "$src" ] || continue
  {
    printf '<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">\n'
    sed -n '1,/<\/style>/p' "$src" | grep -v '<meta name="claude:'
    printf '</head>\n<body>\n'
    sed -n '/<\/style>/,$p' "$src" | tail -n +2
    printf '</body>\n</html>\n'
  } > "$name.html"
  echo "built $name.html"
done
